/// <summary>Rate provider with an explicit base currency.</summary>
public interface IRateProvider
{
    decimal GetRate(string baseCurrency, string quoteCurrency);
}

/// <summary>Table-backed <see cref="IRateProvider"/>.</summary>
public sealed class TableRateProvider : IRateProvider
{
    private readonly Dictionary<string, decimal> _rates = new(StringComparer.OrdinalIgnoreCase)
    {
        ["EURUSD"] = 1.08m,
        ["GBPUSD"] = 1.27m,
        ["EURGBP"] = 0.85m,
    };

    public decimal GetRate(string baseCurrency, string quoteCurrency)
    {
        if (string.Equals(baseCurrency, quoteCurrency, StringComparison.OrdinalIgnoreCase))
            return 1m;
        return _rates.TryGetValue(baseCurrency + quoteCurrency, out var rate) ? rate : 1m;
    }
}
